            SocketAddress localAddress = ioAcceptor.getLocalAddress();
            ioAcceptor.unbind();
            closeManagedSessionsAndDispose(ioAcceptor, true, log);
            log.info("No longer accepting connections on {}", localAddress);
            ioIt.remove();
        }
    }

